// WiFi Direct CLI Tool - Main Entry Point
// Converted from UWP XAML sample to command-line application
// Uses C++/WinRT (standard C++17) instead of C++/CX

#include "pch.h"
#include "Advertiser.h"
#include "Connector.h"
#include <iostream>
#include <string>

void PrintMainMenu()
{
    std::wcout << L"\n========================================" << std::endl;
    std::wcout << L"       Wi-Fi Direct CLI Tool" << std::endl;
    std::wcout << L"========================================" << std::endl;
    std::wcout << L"  1. Advertiser Mode (publish & accept connections)" << std::endl;
    std::wcout << L"  2. Connector Mode  (discover & connect to devices)" << std::endl;
    std::wcout << L"  0. Exit" << std::endl;
    std::wcout << L"========================================" << std::endl;
    std::wcout << L"Select mode: ";
}

int wmain(int argc, wchar_t* argv[])
{
    // Initialize Windows Runtime
    winrt::init_apartment();

    std::wcout << L"Wi-Fi Direct CLI Tool" << std::endl;
    std::wcout << L"Based on Microsoft UWP WiFiDirect Sample" << std::endl;

    while (true)
    {
        PrintMainMenu();

        int choice = 0;
        std::wcin >> choice;

        // Clear the input buffer
        std::wcin.ignore(std::numeric_limits<std::streamsize>::max(), L'\n');

        switch (choice)
        {
        case 1:
            RunAdvertiser();
            break;
        case 2:
            RunConnector();
            break;
        case 0:
            std::wcout << L"Exiting..." << std::endl;
            return 0;
        default:
            std::wcout << L"Invalid choice, please try again." << std::endl;
            break;
        }
    }

    return 0;
}

