// Wi-Fi Direct CLI Tool
// Converted from UWP sample to console application using C++/WinRT

#include <winrt/Windows.Foundation.h>
#include <winrt/Windows.Foundation.Collections.h>
#include <winrt/Windows.Devices.WiFiDirect.h>
#include <winrt/Windows.Devices.Enumeration.h>
#include <winrt/Windows.Networking.Sockets.h>
#include <winrt/Windows.Storage.Streams.h>
#include <winrt/Windows.Security.Credentials.h>

#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <thread>
#include <atomic>
#include <sstream>
#include <cstdlib>

#include "WiFiDirectHelper.h"

using namespace winrt;
using namespace winrt::Windows::Foundation;
using namespace winrt::Windows::Devices::WiFiDirect;
using namespace winrt::Windows::Devices::Enumeration;
using namespace winrt::Windows::Networking::Sockets;
using namespace winrt::Windows::Storage::Streams;

// Global constants
static const std::wstring SERVER_PORT = L"50001";
static const uint8_t CUSTOM_OUI[] = { 0xAA, 0xBB, 0xCC };
static const uint8_t CUSTOM_OUI_TYPE = 0xDD;

// Forward declarations
void RunAdvertiser();
void RunConnector();
void PrintUsage();

// Utility: convert wstring to string for console output
std::string WideToUtf8(const std::wstring& wstr)
{
    if (wstr.empty()) return "";
    int size = WideCharToMultiByte(CP_UTF8, 0, wstr.c_str(), (int)wstr.size(), nullptr, 0, nullptr, nullptr);
    std::string result(size, 0);
    WideCharToMultiByte(CP_UTF8, 0, wstr.c_str(), (int)wstr.size(), &result[0], size, nullptr, nullptr);
    return result;
}

std::string HStringToUtf8(const winrt::hstring& hs)
{
    return WideToUtf8(std::wstring(hs.c_str()));
}

void PrintUsage()
{
    std::cout << "=== Wi-Fi Direct CLI Tool ===" << std::endl;
    std::cout << "Usage: WiFiDirectCLI.exe <mode>" << std::endl;
    std::cout << std::endl;
    std::cout << "Modes:" << std::endl;
    std::cout << "  advertise   - Start as Wi-Fi Direct advertiser (server)" << std::endl;
    std::cout << "  connect     - Start as Wi-Fi Direct connector (client)" << std::endl;
    std::cout << "  help        - Show this help message" << std::endl;
    std::cout << std::endl;
}

// =============================================
// Socket Reader/Writer Helper
// =============================================
class SocketReaderWriter
{
public:
    SocketReaderWriter(StreamSocket socket)
        : m_socket(socket),
          m_reader(socket.InputStream()),
          m_writer(socket.OutputStream()),
          m_currentMessage(L"")
    {
        m_reader.UnicodeEncoding(UnicodeEncoding::Utf8);
        m_reader.ByteOrder(ByteOrder::LittleEndian);
        m_writer.UnicodeEncoding(UnicodeEncoding::Utf8);
        m_writer.ByteOrder(ByteOrder::LittleEndian);
    }

    void WriteMessage(const std::wstring& message)
    {
        try
        {
            winrt::hstring hs(message);
            m_writer.WriteUInt32(m_writer.MeasureString(hs));
            m_writer.WriteString(hs);
            uint32_t bytesWritten = m_writer.StoreAsync().get();
            if (bytesWritten > 0)
            {
                std::cout << "[Socket] Sent message: " << WideToUtf8(message) << std::endl;
            }
            else
            {
                std::cerr << "[Socket] Remote side closed the socket" << std::endl;
            }
        }
        catch (const winrt::hresult_error& e)
        {
            std::cerr << "[Socket] Failed to send message: " << HStringToUtf8(e.message()) << std::endl;
        }
    }

    std::wstring ReadMessageSync()
    {
        try
        {
            uint32_t bytesRead = m_reader.LoadAsync(sizeof(uint32_t)).get();
            if (bytesRead > 0)
            {
                uint32_t strLength = m_reader.ReadUInt32();
                uint32_t strBytesRead = m_reader.LoadAsync(strLength).get();
                if (strBytesRead > 0)
                {
                    winrt::hstring msg = m_reader.ReadString(strLength);
                    m_currentMessage = std::wstring(msg.c_str());
                    std::cout << "[Socket] Got message: " << WideToUtf8(m_currentMessage) << std::endl;
                    return m_currentMessage;
                }
            }
            std::cerr << "[Socket] Remote side closed the socket" << std::endl;
        }
        catch (const winrt::hresult_error& e)
        {
            std::cerr << "[Socket] Failed to read: " << HStringToUtf8(e.message()) << std::endl;
        }
        return L"";
    }

    void StartReadLoop()
    {
        m_readThread = std::thread([this]()
        {
            while (m_running)
            {
                std::wstring msg = ReadMessageSync();
                if (msg.empty())
                    break;
            }
        });
        m_readThread.detach();
    }

    void Close()
    {
        m_running = false;
        m_socket.Close();
    }

    std::wstring GetCurrentMessage() const { return m_currentMessage; }

private:
    StreamSocket m_socket;
    DataReader m_reader;
    DataWriter m_writer;
    std::wstring m_currentMessage;
    std::atomic<bool> m_running{ true };
    std::thread m_readThread;
};

// =============================================
// Connected Device Info
// =============================================
struct ConnectedDeviceInfo
{
    std::wstring displayName;
    WiFiDirectDevice device{ nullptr };
    std::shared_ptr<SocketReaderWriter> socketRW;
};

// =============================================
// Advertiser Mode
// =============================================
void RunAdvertiser()
{
    std::cout << "\n=== Wi-Fi Direct Advertiser Mode ===" << std::endl;
    std::cout << "Options:" << std::endl;
    std::cout << "  [1] Listen State: Normal (default)" << std::endl;
    std::cout << "  [2] Listen State: Intensive" << std::endl;
    std::cout << "  [3] Listen State: None" << std::endl;
    std::cout << "Select listen state [1-3]: ";

    std::string input;
    std::getline(std::cin, input);

    WiFiDirectAdvertisementListenStateDiscoverability listenState =
        WiFiDirectAdvertisementListenStateDiscoverability::Normal;

    if (input == "2")
        listenState = WiFiDirectAdvertisementListenStateDiscoverability::Intensive;
    else if (input == "3")
        listenState = WiFiDirectAdvertisementListenStateDiscoverability::None;

    std::cout << "Enable Autonomous Group Owner mode? [y/N]: ";
    std::getline(std::cin, input);
    bool isAutonomousGO = (input == "y" || input == "Y");

    std::cout << "Enable connection listener? [Y/n]: ";
    std::getline(std::cin, input);
    bool enableListener = (input != "n" && input != "N");

    std::cout << "Group Owner Intent [0-15, default 14]: ";
    std::getline(std::cin, input);
    short goIntent = 14;
    if (!input.empty())
    {
        goIntent = static_cast<short>(std::stoi(input));
        if (goIntent < 0) goIntent = 0;
        if (goIntent > 15) goIntent = 15;
    }

    // Data structures
    std::vector<ConnectedDeviceInfo> connectedDevices;
    std::mutex devicesMutex;

    // Create publisher
    WiFiDirectAdvertisementPublisher publisher;
    publisher.Advertisement().IsAutonomousGroupOwnerEnabled(isAutonomousGO);
    publisher.Advertisement().ListenStateDiscoverability(listenState);

    // Status changed handler
    auto statusToken = publisher.StatusChanged([](WiFiDirectAdvertisementPublisher const& sender,
        WiFiDirectAdvertisementPublisherStatusChangedEventArgs const& args)
    {
        std::cout << "[Advertiser] Status changed: " << static_cast<int>(args.Status())
                  << " Error: " << static_cast<int>(args.Error()) << std::endl;
    });

    // Connection listener
    WiFiDirectConnectionListener listener{ nullptr };
    winrt::event_token connectionToken{};

    if (enableListener)
    {
        listener = WiFiDirectConnectionListener();

        connectionToken = listener.ConnectionRequested(
            [&connectedDevices, &devicesMutex, goIntent](WiFiDirectConnectionListener const&,
                WiFiDirectConnectionRequestedEventArgs const& args)
        {
            try
            {
                auto connectionRequest = args.GetConnectionRequest();
                auto deviceName = connectionRequest.DeviceInformation().Name();

                std::cout << "\n[Advertiser] Connection request received from: "
                          << HStringToUtf8(deviceName) << std::endl;
                std::cout << "Accept connection? [Y/n]: ";

                std::string response;
                std::getline(std::cin, response);

                if (response == "n" || response == "N")
                {
                    std::cout << "[Advertiser] Connection declined." << std::endl;
                    return;
                }

                std::cout << "[Advertiser] Connecting to " << HStringToUtf8(deviceName) << "..." << std::endl;

                WiFiDirectConnectionParameters connectionParams;
                connectionParams.GroupOwnerIntent(goIntent);

                auto wfdDevice = WiFiDirectDevice::FromIdAsync(
                    connectionRequest.DeviceInformation().Id(), connectionParams).get();

                wfdDevice.ConnectionStatusChanged([](WiFiDirectDevice const& sender, auto const&)
                {
                    std::cout << "[Advertiser] Connection status changed: "
                              << static_cast<int>(sender.ConnectionStatus()) << std::endl;
                });

                auto endpointPairs = wfdDevice.GetConnectionEndpointPairs();
                auto localHost = endpointPairs.GetAt(0).LocalHostName();

                std::cout << "[Advertiser] L2 connected, listening on "
                          << HStringToUtf8(localHost.DisplayName())
                          << ":" << WideToUtf8(SERVER_PORT) << std::endl;

                // Start TCP listener
                StreamSocketListener socketListener;
                std::shared_ptr<SocketReaderWriter> socketRW;
                std::atomic<bool> clientConnected{ false };

                socketListener.ConnectionReceived(
                    [&socketRW, &clientConnected, &connectedDevices, &devicesMutex, &wfdDevice]
                    (StreamSocketListener const&, StreamSocketListenerConnectionReceivedEventArgs const& args)
                {
                    std::cout << "[Advertiser] Client connected on L4 layer" << std::endl;
                    auto serverSocket = args.Socket();
                    socketRW = std::make_shared<SocketReaderWriter>(serverSocket);

                    // Read session ID from client
                    std::wstring sessionId = socketRW->ReadMessageSync();
                    if (!sessionId.empty())
                    {
                        std::cout << "[Advertiser] Session established: " << WideToUtf8(sessionId) << std::endl;

                        std::lock_guard<std::mutex> lock(devicesMutex);
                        ConnectedDeviceInfo info;
                        info.displayName = sessionId;
                        info.device = wfdDevice;
                        info.socketRW = socketRW;
                        connectedDevices.push_back(info);

                        // Start continuous reading
                        socketRW->StartReadLoop();
                    }
                    clientConnected = true;
                });

                socketListener.BindEndpointAsync(localHost, winrt::hstring(SERVER_PORT)).get();

                std::cout << "[Advertiser] Waiting for client socket connection..." << std::endl;

                // Wait for client to connect (with timeout)
                int waitCount = 0;
                while (!clientConnected && waitCount < 300)  // 30 second timeout
                {
                    std::this_thread::sleep_for(std::chrono::milliseconds(100));
                    waitCount++;
                }

                if (!clientConnected)
                {
                    std::cout << "[Advertiser] Timeout waiting for client socket." << std::endl;
                }
            }
            catch (const winrt::hresult_error& e)
            {
                std::cerr << "[Advertiser] Error handling connection: " << HStringToUtf8(e.message()) << std::endl;
            }
        });
    }

    // Start advertisement
    try
    {
        publisher.Start();
        std::cout << "[Advertiser] Advertisement started, waiting for connections..." << std::endl;
    }
    catch (const winrt::hresult_error& e)
    {
        std::cerr << "[Advertiser] Error starting advertisement: " << HStringToUtf8(e.message()) << std::endl;
        return;
    }

    // Interactive command loop
    std::cout << "\nCommands:" << std::endl;
    std::cout << "  send <index> <message> - Send message to connected device" << std::endl;
    std::cout << "  list                   - List connected devices" << std::endl;
    std::cout << "  close <index>          - Close connection to device" << std::endl;
    std::cout << "  stop                   - Stop advertisement and exit" << std::endl;
    std::cout << std::endl;

    while (true)
    {
        std::cout << "> ";
        std::string cmd;
        std::getline(std::cin, cmd);

        if (cmd == "stop" || cmd == "quit" || cmd == "exit")
        {
            break;
        }
        else if (cmd == "list")
        {
            std::lock_guard<std::mutex> lock(devicesMutex);
            if (connectedDevices.empty())
            {
                std::cout << "No connected devices." << std::endl;
            }
            else
            {
                for (size_t i = 0; i < connectedDevices.size(); i++)
                {
                    std::cout << "  [" << i << "] " << WideToUtf8(connectedDevices[i].displayName) << std::endl;
                }
            }
        }
        else if (cmd.substr(0, 5) == "send ")
        {
            std::istringstream iss(cmd.substr(5));
            int idx;
            std::string msg;
            iss >> idx;
            std::getline(iss, msg);
            if (!msg.empty() && msg[0] == ' ') msg = msg.substr(1);

            std::lock_guard<std::mutex> lock(devicesMutex);
            if (idx >= 0 && idx < (int)connectedDevices.size() && connectedDevices[idx].socketRW)
            {
                std::wstring wmsg(msg.begin(), msg.end());
                connectedDevices[idx].socketRW->WriteMessage(wmsg);
            }
            else
            {
                std::cerr << "Invalid device index." << std::endl;
            }
        }
        else if (cmd.substr(0, 6) == "close ")
        {
            int idx = std::stoi(cmd.substr(6));
            std::lock_guard<std::mutex> lock(devicesMutex);
            if (idx >= 0 && idx < (int)connectedDevices.size())
            {
                connectedDevices[idx].socketRW->Close();
                connectedDevices[idx].device.Close();
                std::cout << "Closed: " << WideToUtf8(connectedDevices[idx].displayName) << std::endl;
                connectedDevices.erase(connectedDevices.begin() + idx);
            }
            else
            {
                std::cerr << "Invalid device index." << std::endl;
            }
        }
        else if (!cmd.empty())
        {
            std::cout << "Unknown command. Use: send, list, close, stop" << std::endl;
        }
    }

    // Cleanup
    try
    {
        publisher.Stop();
        publisher.StatusChanged(statusToken);
        if (listener)
        {
            listener.ConnectionRequested(connectionToken);
        }
    }
    catch (...) {}

    std::lock_guard<std::mutex> lock(devicesMutex);
    for (auto& dev : connectedDevices)
    {
        try
        {
            if (dev.socketRW) dev.socketRW->Close();
            dev.device.Close();
        }
        catch (...) {}
    }

    std::cout << "[Advertiser] Stopped." << std::endl;
}

// =============================================
// Connector Mode
// =============================================
void RunConnector()
{
    std::cout << "\n=== Wi-Fi Direct Connector Mode ===" << std::endl;

    std::cout << "Device selector type:" << std::endl;
    std::cout << "  [1] Device Interface (default)" << std::endl;
    std::cout << "  [2] Association Endpoint" << std::endl;
    std::cout << "Select [1-2]: ";

    std::string input;
    std::getline(std::cin, input);

    WiFiDirectDeviceSelectorType selectorType = WiFiDirectDeviceSelectorType::DeviceInterface;
    if (input == "2")
        selectorType = WiFiDirectDeviceSelectorType::AssociationEndpoint;

    std::cout << "Group Owner Intent [0-15, default 14]: ";
    std::getline(std::cin, input);
    short goIntent = 14;
    if (!input.empty())
    {
        goIntent = static_cast<short>(std::stoi(input));
        if (goIntent < 0) goIntent = 0;
        if (goIntent > 15) goIntent = 15;
    }

    // Discovered devices
    struct DiscoveredDeviceInfo
    {
        winrt::hstring id;
        winrt::hstring name;
    };

    std::vector<DiscoveredDeviceInfo> discoveredDevices;
    std::mutex discoveryMutex;
    std::vector<ConnectedDeviceInfo> connectedDevices;
    std::mutex connectionMutex;

    // Create device watcher
    auto deviceSelector = WiFiDirectDevice::GetDeviceSelector(selectorType);

    winrt::Windows::Foundation::Collections::IVector<winrt::hstring> requestedProperties =
        winrt::single_threaded_vector<winrt::hstring>();
    requestedProperties.Append(L"System.Devices.WiFiDirect.InformationElements");

    auto deviceWatcher = DeviceInformation::CreateWatcher(deviceSelector, requestedProperties);

    deviceWatcher.Added([&discoveredDevices, &discoveryMutex](DeviceWatcher const&, DeviceInformation const& info)
    {
        std::lock_guard<std::mutex> lock(discoveryMutex);
        DiscoveredDeviceInfo dev;
        dev.id = info.Id();
        dev.name = info.Name();
        discoveredDevices.push_back(dev);
        std::cout << "\n[Watcher] Device found: " << HStringToUtf8(info.Name())
                  << " (Total: " << discoveredDevices.size() << ")" << std::endl;
        std::cout << "> " << std::flush;
    });

    deviceWatcher.Removed([&discoveredDevices, &discoveryMutex](DeviceWatcher const&, DeviceInformationUpdate const& update)
    {
        std::lock_guard<std::mutex> lock(discoveryMutex);
        for (auto it = discoveredDevices.begin(); it != discoveredDevices.end(); ++it)
        {
            if (it->id == update.Id())
            {
                std::cout << "\n[Watcher] Device removed: " << HStringToUtf8(it->name) << std::endl;
                std::cout << "> " << std::flush;
                discoveredDevices.erase(it);
                break;
            }
        }
    });

    deviceWatcher.EnumerationCompleted([](DeviceWatcher const&, auto const&)
    {
        std::cout << "\n[Watcher] Enumeration completed." << std::endl;
        std::cout << "> " << std::flush;
    });

    deviceWatcher.Stopped([](DeviceWatcher const&, auto const&)
    {
        std::cout << "\n[Watcher] Stopped." << std::endl;
    });

    // Start watching
    deviceWatcher.Start();
    std::cout << "[Connector] Watching for Wi-Fi Direct devices..." << std::endl;

    // Interactive command loop
    std::cout << "\nCommands:" << std::endl;
    std::cout << "  devices                - List discovered devices" << std::endl;
    std::cout << "  connect <index>        - Connect to a discovered device" << std::endl;
    std::cout << "  send <index> <message> - Send message to connected device" << std::endl;
    std::cout << "  list                   - List connected devices" << std::endl;
    std::cout << "  close <index>          - Close connection to device" << std::endl;
    std::cout << "  stop                   - Stop watcher and exit" << std::endl;
    std::cout << std::endl;

    while (true)
    {
        std::cout << "> ";
        std::string cmd;
        std::getline(std::cin, cmd);

        if (cmd == "stop" || cmd == "quit" || cmd == "exit")
        {
            break;
        }
        else if (cmd == "devices")
        {
            std::lock_guard<std::mutex> lock(discoveryMutex);
            if (discoveredDevices.empty())
            {
                std::cout << "No devices discovered yet." << std::endl;
            }
            else
            {
                for (size_t i = 0; i < discoveredDevices.size(); i++)
                {
                    std::cout << "  [" << i << "] " << HStringToUtf8(discoveredDevices[i].name)
                              << " (" << HStringToUtf8(discoveredDevices[i].id) << ")" << std::endl;
                }
            }
        }
        else if (cmd.substr(0, 8) == "connect ")
        {
            int idx = std::stoi(cmd.substr(8));
            winrt::hstring deviceId;
            winrt::hstring deviceName;

            {
                std::lock_guard<std::mutex> lock(discoveryMutex);
                if (idx < 0 || idx >= (int)discoveredDevices.size())
                {
                    std::cerr << "Invalid device index." << std::endl;
                    continue;
                }
                deviceId = discoveredDevices[idx].id;
                deviceName = discoveredDevices[idx].name;
            }

            std::cout << "[Connector] Connecting to " << HStringToUtf8(deviceName) << "..." << std::endl;

            try
            {
                WiFiDirectConnectionParameters connectionParams;
                connectionParams.GroupOwnerIntent(goIntent);

                auto wfdDevice = WiFiDirectDevice::FromIdAsync(deviceId, connectionParams).get();

                wfdDevice.ConnectionStatusChanged([](WiFiDirectDevice const& sender, auto const&)
                {
                    std::cout << "[Connector] Connection status changed: "
                              << static_cast<int>(sender.ConnectionStatus()) << std::endl;
                });

                auto endpointPairs = wfdDevice.GetConnectionEndpointPairs();
                auto remoteHost = endpointPairs.GetAt(0).RemoteHostName();

                std::cout << "[Connector] L2 connected, connecting to "
                          << HStringToUtf8(remoteHost.DisplayName())
                          << ":" << WideToUtf8(SERVER_PORT) << std::endl;

                // Wait for server to start listening
                std::cout << "[Connector] Waiting for server socket..." << std::endl;
                std::this_thread::sleep_for(std::chrono::seconds(5));

                // Connect L4
                StreamSocket clientSocket;
                clientSocket.ConnectAsync(remoteHost, winrt::hstring(SERVER_PORT)).get();

                auto socketRW = std::make_shared<SocketReaderWriter>(clientSocket);

                std::wstring sessionId = L"Session_" + std::to_wstring(rand());

                ConnectedDeviceInfo info;
                info.displayName = sessionId;
                info.device = wfdDevice;
                info.socketRW = socketRW;

                {
                    std::lock_guard<std::mutex> lock(connectionMutex);
                    connectedDevices.push_back(info);
                }

                // Start reading messages
                socketRW->StartReadLoop();

                // Send session ID
                socketRW->WriteMessage(sessionId);

                std::cout << "[Connector] Connected on L4 layer, session: " << WideToUtf8(sessionId) << std::endl;
            }
            catch (const winrt::hresult_error& e)
            {
                std::cerr << "[Connector] Connection error: " << HStringToUtf8(e.message()) << std::endl;
            }
        }
        else if (cmd == "list")
        {
            std::lock_guard<std::mutex> lock(connectionMutex);
            if (connectedDevices.empty())
            {
                std::cout << "No connected devices." << std::endl;
            }
            else
            {
                for (size_t i = 0; i < connectedDevices.size(); i++)
                {
                    std::cout << "  [" << i << "] " << WideToUtf8(connectedDevices[i].displayName) << std::endl;
                }
            }
        }
        else if (cmd.substr(0, 5) == "send ")
        {
            std::istringstream iss(cmd.substr(5));
            int idx;
            std::string msg;
            iss >> idx;
            std::getline(iss, msg);
            if (!msg.empty() && msg[0] == ' ') msg = msg.substr(1);

            std::lock_guard<std::mutex> lock(connectionMutex);
            if (idx >= 0 && idx < (int)connectedDevices.size() && connectedDevices[idx].socketRW)
            {
                std::wstring wmsg(msg.begin(), msg.end());
                connectedDevices[idx].socketRW->WriteMessage(wmsg);
            }
            else
            {
                std::cerr << "Invalid device index." << std::endl;
            }
        }
        else if (cmd.substr(0, 6) == "close ")
        {
            int idx = std::stoi(cmd.substr(6));
            std::lock_guard<std::mutex> lock(connectionMutex);
            if (idx >= 0 && idx < (int)connectedDevices.size())
            {
                connectedDevices[idx].socketRW->Close();
                connectedDevices[idx].device.Close();
                std::cout << "Closed: " << WideToUtf8(connectedDevices[idx].displayName) << std::endl;
                connectedDevices.erase(connectedDevices.begin() + idx);
            }
            else
            {
                std::cerr << "Invalid device index." << std::endl;
            }
        }
        else if (!cmd.empty())
        {
            std::cout << "Unknown command. Use: devices, connect, send, list, close, stop" << std::endl;
        }
    }

    // Cleanup
    try
    {
        deviceWatcher.Stop();
    }
    catch (...) {}

    std::lock_guard<std::mutex> lock(connectionMutex);
    for (auto& dev : connectedDevices)
    {
        try
        {
            if (dev.socketRW) dev.socketRW->Close();
            dev.device.Close();
        }
        catch (...) {}
    }

    std::cout << "[Connector] Stopped." << std::endl;
}

// =============================================
// Main Entry Point
// =============================================
int main(int argc, char* argv[])
{
    // Initialize WinRT
    winrt::init_apartment();

    if (argc < 2)
    {
        PrintUsage();
        return 1;
    }

    std::string mode(argv[1]);

    if (mode == "advertise")
    {
        RunAdvertiser();
    }
    else if (mode == "connect")
    {
        RunConnector();
    }
    else if (mode == "help" || mode == "--help" || mode == "-h")
    {
        PrintUsage();
    }
    else
    {
        std::cerr << "Unknown mode: " << mode << std::endl;
        PrintUsage();
        return 1;
    }

    winrt::uninit_apartment();
    return 0;
}

